style.css:
@-moz-document domain("calendar.google.com") {
/* Add a cherry blossom background */
  body {
    background: url('https://i.imgur.com/EZUVkDg.jpg') no-repeat center center fixed;
    background-size: cover;
    font-family: "Arial", sans-serif;
  }

  /* Set transparency for the calendar content */
  .lv-header, .lv-container, .t2ovdb {
    background: rgba(255, 255, 255, 0.9) !important;
    border-radius: 10px;
  }

  /* Pink text and accents for headers and titles */
  .gb_4d, .gb_1e, .gb_ke, .cQgiCd, .T2YZF, .Jmftzc, .XPtOyb {
    color: #ff7eb9 !important; /* Soft pink */
  }

  /* Calendar event colors */
  .aKjvCe, .tlJBeG, .cbxkDd, .mg8Lt {
    color: #ffffff !important; /* White text */
    background: #ffc6e7 !important; /* Light pink background */
    border-color: #ff99cc !important; /* Darker pink border */
  }

  /* Button hover effects */
  .uArJ5e.UQuaGc.Y5sE8d:hover {
    background: #ff99cc !important;
    color: white !important;
  }

  /* Scrollbars in soft pink */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #ffe6f1;
  }

  ::-webkit-scrollbar-thumb {
    background: #ff7eb9;
    border-radius: 5px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #ff4fa8;
  }
}
